/* Start here (demos/lib/starthere.js). Generated by tools/activities.py (through tools/courses.py) from curriculum/start-here.json:
   edit the data, not this file. demos/lib/vd.js loads it on every demo; it does nothing on a demo with no entry.
   A fold in the sidebar under the worksheet and How this works buttons: Start here, about 5 minutes (one question, a Set it up
   link that reopens the demo in that setup, what to do, and What you should see, closed so a student predicts first), then
   Explore further, about 15 minutes (up to three short follow ups, each with its own setup). ?start=1 in the address opens it.
   Set it up keeps ?course=, ?topic= and ?lang= and replaces every other setting (set= is the demo's own Copy link format).
   English and Spanish are both here; the fold is data-i18n-skip so the page translation leaves it alone.
   Each demo's entry is its own small file, demos/lib/starthere/<demo>.js (2026-11-18: one file with every entry was half of
   what a demo page downloaded). FILES names them in full so the offline zip finds them; DATA holds entries inline only in a
   test build (python3 tools/activities.py --js, used by tools/startcheck.cjs --data). */
(() => {
  const FILES = {"active-galaxies":"starthere/active-galaxies.js","between-the-stars":"starthere/between-the-stars.js","blackbody":"starthere/blackbody.js","bose-einstein":"starthere/bose-einstein.js","bragg-peak":"starthere/bragg-peak.js","bz-reaction":"starthere/bz-reaction.js","capacitors":"starthere/capacitors.js","celestial-sphere":"starthere/celestial-sphere.js","charged-particles":"starthere/charged-particles.js","chladni":"starthere/chladni.js","circuits":"starthere/circuits.js","collisions":"starthere/collisions.js","color-vision":"starthere/color-vision.js","comets":"starthere/comets.js","coulomb-sandbox":"starthere/coulomb-sandbox.js","craters":"starthere/craters.js","ct-range":"starthere/ct-range.js","currents-fields":"starthere/currents-fields.js","diffraction-grating":"starthere/diffraction-grating.js","distance-ladder":"starthere/distance-ladder.js","dosimetry":"starthere/dosimetry.js","early-universe":"starthere/early-universe.js","em-waves":"starthere/em-waves.js","energy-track":"starthere/energy-track.js","entropy":"starthere/entropy.js","equivalence-gravity":"starthere/equivalence-gravity.js","exoplanets":"starthere/exoplanets.js","fate-of-the-universe":"starthere/fate-of-the-universe.js","fluids":"starthere/fluids.js","forces":"starthere/forces.js","galaxy-clusters":"starthere/galaxy-clusters.js","galaxy-collisions":"starthere/galaxy-collisions.js","gas-heat-capacity":"starthere/gas-heat-capacity.js","gauss-law":"starthere/gauss-law.js","giant-planets":"starthere/giant-planets.js","granular-flow":"starthere/granular-flow.js","gravitational-waves":"starthere/gravitational-waves.js","gravity-near-earth":"starthere/gravity-near-earth.js","gyroscope":"starthere/gyroscope.js","hearing":"starthere/hearing.js","hydrogen-orbitals":"starthere/hydrogen-orbitals.js","ideal-gas":"starthere/ideal-gas.js","induction":"starthere/induction.js","inside-a-planet":"starthere/inside-a-planet.js","inside-the-sun":"starthere/inside-the-sun.js","instrument-builder":"starthere/instrument-builder.js","kepler-orbits":"starthere/kepler-orbits.js","lagrange-points":"starthere/lagrange-points.js","life-in-the-universe":"starthere/life-in-the-universe.js","magnetic-force":"starthere/magnetic-force.js","milky-way":"starthere/milky-way.js","molecules":"starthere/molecules.js","moon-phases":"starthere/moon-phases.js","motion-graphs":"starthere/motion-graphs.js","nerve-signals":"starthere/nerve-signals.js","neutron-stars":"starthere/neutron-stars.js","nuclear-reactions":"starthere/nuclear-reactions.js","optics-bench":"starthere/optics-bench.js","osmosis":"starthere/osmosis.js","particles":"starthere/particles.js","pendulum":"starthere/pendulum.js","photon-interactions":"starthere/photon-interactions.js","planet-temperatures":"starthere/planet-temperatures.js","projectile-drag":"starthere/projectile-drag.js","proton-qa":"starthere/proton-qa.js","quantum-coin":"starthere/quantum-coin.js","quantum-waves":"starthere/quantum-waves.js","radioactive-decay":"starthere/radioactive-decay.js","radiobiology":"starthere/radiobiology.js","rainbows":"starthere/rainbows.js","resolution":"starthere/resolution.js","resonances":"starthere/resonances.js","retrograde-motion":"starthere/retrograde-motion.js","ripple-tank":"starthere/ripple-tank.js","room-acoustics":"starthere/room-acoustics.js","rotating-frames":"starthere/rotating-frames.js","rotation":"starthere/rotation.js","seasons":"starthere/seasons.js","shielding-rooms":"starthere/shielding-rooms.js","solar-system-formation":"starthere/solar-system-formation.js","solids":"starthere/solids.js","spacetime":"starthere/spacetime.js","spectra":"starthere/spectra.js","spectral-classes":"starthere/spectral-classes.js","springs":"starthere/springs.js","star-birth":"starthere/star-birth.js","starlight":"starthere/starlight.js","sun-surface":"starthere/sun-surface.js","superfluid-helium":"starthere/superfluid-helium.js","surface-tension":"starthere/surface-tension.js","telescope-aberrations":"starthere/telescope-aberrations.js","temperature":"starthere/temperature.js","tides":"starthere/tides.js","units":"starthere/units.js"};
  const DATA = {};
  const UI = {"en":{"title":"Start here","five":"about 5 min","fifteen":"about 15 min","setup":"Set it up","hint":"reopens the demo ready","see":"What you should see","explore":"Explore further"},"es":{"title":"Empieza aquí","five":"unos 5 min","fifteen":"unos 15 min","setup":"Prepáralo","hint":"vuelve a abrir la demostración lista","see":"Lo que deberías ver","explore":"Explora más"}};
  const here = location.pathname.split('/').pop().replace(/\.html$/, '');
  if (!DATA[here] && !FILES[here]) return;
  const self = document.currentScript;
  const run = (e) => {
    const rail = document.querySelector('.rail');
    if (!rail || document.getElementById('vdStart')) return;
    const L = (window.VDI18N && VDI18N.lang === 'es') ? 'es' : 'en';
    const T = (o, k) => (L === 'es' && o[k + '_es']) || o[k];
    const u = UI[L];
    const P = new URLSearchParams(location.search);
    const go = (setup, step) => {
      const q = new URLSearchParams(setup || '');
      for (const k of ['course', 'topic', 'lang']) if (P.get(k)) q.set(k, P.get(k));
      q.set('start', step || '1');
      return here + '.html?' + q.toString();
    };
    const step = P.get('start');
    const d = document.createElement('details');
    d.className = 'vd-start'; d.id = 'vdStart'; d.setAttribute('data-i18n-skip', ''); d.setAttribute('data-vd-noshare', '');
    if (step) d.open = true;
    const ex = (e.explore || []).map((x, i) => `<li${step === 'e' + (i + 1) ? ' class="on"' : ''}><p>${T(x, 'do')} <a class="vd-start-go sm" href="${go(x.setup, 'e' + (i + 1))}">${u.setup}</a></p>`
      + `<details><summary>${u.see}</summary><p>${T(x, 'see')}</p></details></li>`).join('');
    d.innerHTML = `<summary><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4l14 8-14 8z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/></svg>${u.title}<span class="vd-start-min">${u.five}</span></summary>`
      + `<div class="vd-start-body"><p class="vd-start-q">${T(e, 'q')}</p>`
      + `<p><a class="vd-start-go" href="${go(e.setup, '1')}">${u.setup}</a> <span class="vd-start-hint">${u.hint}</span></p>`
      + `<p>${T(e, 'do')}</p>`
      + `<details class="vd-start-see"><summary>${u.see}</summary><p>${T(e, 'see')}</p></details>`
      + (ex ? `<h3>${u.explore}<span class="vd-start-min">${u.fifteen}</span></h3><ol>${ex}</ol>` : '')
      + `</div>`;
    const css = document.createElement('style');
    css.textContent = `.vd-start{margin:10px 14px 0;border:1.5px solid var(--accent);border-radius:9px;background:color-mix(in srgb,var(--accent) 6%,var(--surface))}
.vd-start>summary{display:flex;align-items:center;gap:8px;padding:9px 12px;font-weight:700;font-size:.95rem;color:var(--accent);cursor:pointer;list-style:none}
.vd-start>summary::-webkit-details-marker{display:none}
.vd-start>summary svg{width:18px;height:18px;flex:none}
.vd-start>summary::after{content:"▾";margin-left:auto;font-size:.85rem}.vd-start[open]>summary::after{content:"▴"}
.vd-start>summary:focus-visible,.vd-start a:focus-visible,.vd-start summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.vd-start-min{font-weight:400;font-size:.78rem;color:var(--muted);margin-left:4px}
.vd-start-body{padding:0 12px 10px;font-size:.9rem;line-height:1.45;color:var(--ink)}
.vd-start-body p{margin:6px 0}.vd-start-q{font-weight:700;font-size:.97rem}
.vd-start-go{display:inline-block;padding:4px 10px;border-radius:7px;background:var(--accent);color:var(--canvas);font-weight:700;text-decoration:none;font-size:.86rem}
.vd-start-go.sm{padding:1px 8px;font-size:.8rem}
.vd-start-hint{font-size:.78rem;color:var(--muted)}
.vd-start details summary{cursor:pointer;color:var(--accent);font-weight:600;font-size:.86rem}
.vd-start h3{margin:12px 0 4px;font-size:.88rem;font-family:var(--font-mono,monospace);text-transform:uppercase;letter-spacing:.03em;color:var(--muted)}
.vd-start ol{margin:0;padding-left:20px}.vd-start li{margin:0 0 8px}.vd-start li.on>p{font-weight:600}
@media print{.vd-start{display:none}}`;
    document.head.appendChild(css);
    const after = rail.querySelector('#vdHowTo') || rail.querySelector('.handout-menu, .handout');
    if (after) after.insertAdjacentElement('afterend', d); else rail.insertBefore(d, rail.firstChild);
    if (step && step !== '1') { const li = d.querySelector('li.on'); if (li) li.scrollIntoView({ block: 'nearest' }); }
    window.dispatchEvent(new Event('resize'));
  };
  /* after the demo has built its sidebar and How this works button */
  const show = (e) => { if (document.readyState === 'complete') setTimeout(() => run(e), 0); else window.addEventListener('load', () => setTimeout(() => run(e), 0)); };
  if (DATA[here]) { show(DATA[here]); return; }
  window.VDStartHere = show;   /* the demo's file calls it with the entry */
  const s = document.createElement('script'); s.async = true;
  s.src = (self && self.src ? self.src.replace(/starthere\.js([?#].*)?$/, '') : 'lib/') + FILES[here];
  document.head.appendChild(s);
})();
